let setupEmail=null;
const scopeNames={all:'Toàn hệ thống',iid:'Cấp IID',department:'Bộ phận được giao',personal:'Cá nhân được giao'};
function totalScore(ks,p){if(!ks.length)return null;return user.role==='admin'?KPI.composite(state,ks,p):state.scopeScores?.[p.type+'|'+p.value+'|'+KPI.key(ks[0])]??null;}
function applyMenus(){document.querySelectorAll('nav button').forEach(b=>{b.hidden=!user||b.dataset.view==='members'&&user.role!=='admin'||user.mustChange&&b.dataset.view!=='account';b.classList.toggle('active',b.dataset.view===view)});$('#import').parentElement.hidden=!user||user.role!=='admin';$('#backup').hidden=!user||user.mustChange;$('#logout').hidden=!user;$('.avatar').textContent=user?roleNames[user.role]:'Khách';}
function logoutUI(){user=null;state=null;version=0;stale=false;view='overview';document.querySelectorAll('dialog[open]').forEach(d=>d.close());document.body.classList.add('signedout');applyMenus();}
function renderLogin(){logoutUI();$('#app').innerHTML=`<div class="loginbox"><div class="eyebrow">IID · KPI WORKSPACE 2027</div><h1>${setupEmail?'Thiết lập mật khẩu quản trị':'Đăng nhập tài khoản KPI'}</h1><p>${setupEmail?'Xác thực quản trị hiện có đã hoàn tất. Hãy tự đặt mật khẩu để dùng tài khoản email/mật khẩu.':'Sử dụng email và mật khẩu được quản trị cấp.'}</p><form id="loginform"><label>Email<input name="email" type="email" autocomplete="username" required value="${esc(setupEmail||'')}" ${setupEmail?'readonly':''}></label><label>${setupEmail?'Mật khẩu mới':'Mật khẩu'}<input name="password" type="password" autocomplete="${setupEmail?'new-password':'current-password'}" required ${setupEmail?'minlength="15"':''}></label>${setupEmail?'<label>Nhập lại mật khẩu mới<input name="confirm" type="password" autocomplete="new-password" required></label><p class="mini">Ít nhất 15 ký tự; tối đa 72 byte UTF-8.</p>':''}<p id="loginerror" role="alert"></p><button class="primary">${setupEmail?'Thiết lập & đăng nhập':'Đăng nhập'}</button></form>${setupEmail?'<p><button onclick="setupEmail=null;renderLogin()">Dùng tài khoản đã có mật khẩu</button></p>':'<p class="mini">Quên mật khẩu? Liên hệ quản trị để cấp lại mật khẩu tạm.</p><a class="mini" href="/signin-with-chatgpt?return_to=%2F" target="_top">Thiết lập mật khẩu lần đầu cho quản trị hiện có</a>'}</div>`;$('#loginform').onsubmit=async e=>{e.preventDefault();let f=e.target,b=f.querySelector('button');if(setupEmail&&f.elements.password.value!==f.elements.confirm.value){$('#loginerror').textContent='Hai mật khẩu chưa khớp.';return}b.disabled=true;try{let x=await req(setupEmail?'/auth/setup':'/auth/login','POST',{email:f.elements.email.value,password:f.elements.password.value});setupEmail=null;user=x.user;await enterWorkspace()}catch(e){$('#loginerror').textContent=e.message}finally{b.disabled=false}};}
async function enterWorkspace(){document.body.classList.remove('signedout');applyMenus();if(user.mustChange){view='account';render();return}let x=await req('/api/workspace');state=x.state?KPI.migrate(x.state):null;version=x.version;view='overview';render();}
function renderAccount(){if(!user)return renderLogin();$('#app').innerHTML=head('Tài khoản & mật khẩu','Tự quản lý mật khẩu cho tài khoản của bạn.')+`<div class="panel"><h2>${esc(user.name)}</h2><p>${esc(user.email)} · ${esc(roleNames[user.role])}<br>Phạm vi: ${esc(scopeNames[user.scope_level])}${user.team?' · '+esc(user.team):''}</p>${user.mustChange?'<div class="alert">Bạn đang dùng mật khẩu tạm. Hãy đổi mật khẩu trước khi xem hoặc cập nhật KPI.</div>':''}<form id="passwordform" class="fields"><label>Mật khẩu hiện tại<input name="currentPassword" type="password" autocomplete="current-password" required></label><label>Mật khẩu mới<input name="newPassword" type="password" minlength="15" autocomplete="new-password" required></label><label>Nhập lại mật khẩu mới<input name="confirm" type="password" autocomplete="new-password" required></label><button class="primary">Đổi mật khẩu</button></form><p class="mini">Ít nhất 15 ký tự, tối đa 72 byte UTF-8. Các phiên đăng nhập trước sẽ bị thu hồi khi đổi mật khẩu.</p></div>`;$('#passwordform').onsubmit=async e=>{e.preventDefault();let f=e.target;if(f.elements.newPassword.value!==f.elements.confirm.value)return toast('Hai mật khẩu mới chưa khớp.');let b=f.querySelector('button');b.disabled=true;try{let x=await req('/auth/change-password','POST',{currentPassword:f.elements.currentPassword.value,newPassword:f.elements.newPassword.value});user=x.user;await enterWorkspace();toast('Đã đổi mật khẩu và thu hồi các phiên cũ.')}catch(e){toast(e.message)}finally{b.disabled=false}};}
function showTemporary(email,p){let d=document.createElement('dialog');d.className='temporary';d.innerHTML=`<h2>Mật khẩu tạm</h2><p>Tài khoản ${esc(email)}. Mật khẩu chỉ hiển thị lần này. Chuyển riêng cho người được cấp; họ phải đổi khi đăng nhập lần đầu.</p><input readonly aria-label="Mật khẩu tạm" value="${esc(p)}"><p><button class="primary">Đã ghi nhận</button></p>`;document.body.appendChild(d);d.querySelector('button').onclick=()=>d.close();d.onclose=()=>d.remove();d.showModal();}
function renderMembers(){$('#app').innerHTML=head('Tài khoản & phạm vi','Quản trị cấp tài khoản email/mật khẩu và phạm vi xem cho từng người.')+`<form id="memberform" class="panel fields"><label>Email<input name="email" type="email" required></label><label>Họ tên<input name="name" required></label><label>Vai trò<select name="role"><option value="contributor">Cá nhân</option><option value="manager">Quản lý bộ phận</option><option value="leader">Cấp IID</option><option value="viewer">Chỉ xem</option><option value="admin">Quản trị</option></select></label><label>Bộ phận<input name="team"></label><label>Cấp được xem (cho vai trò Chỉ xem)<select name="scope_level"><option value="personal">Cá nhân theo email tài khoản</option><option value="department">Bộ phận được giao</option><option value="iid">IID</option></select></label><label class="check"><input name="disabled" type="checkbox"> Khóa tài khoản</label><button class="primary">Cấp tài khoản / lưu quyền</button></form><p class="mini">Tài khoản mới được cấp mật khẩu tạm tự động. Với tài khoản đã có, dùng Cấp lại mật khẩu khi cần. Cá nhân được giao KPI bằng đúng email tài khoản.</p><div id="memberlist" class="sectionspace">Đang tải…</div><div id="auditlist" class="sectionspace"></div>`;$('#memberform').onsubmit=async e=>{e.preventDefault();let data=Object.fromEntries(new FormData(e.target));data.disabled=e.target.elements.disabled.checked;try{let x=await req('/api/members','POST',data);await loadAccountList();if(x.temporaryPassword)showTemporary(x.email,x.temporaryPassword);else toast('Đã lưu quyền; phiên cũ của tài khoản này đã thu hồi.');if(data.email.toLowerCase()===user.email){setupEmail=null;renderLogin()}}catch(e){toast(e.message)}};loadAccountList();}
let accountList=[];
async function loadAccountList(){try{let [ms,logs]=await Promise.all([req('/api/members'),req('/api/audit')]);if(view!=='members')return;accountList=ms;$('#memberlist').innerHTML=`<div class="tablewrap"><table><thead><tr><th>TÀI KHOẢN</th><th>VAI TRÒ / CẤP</th><th>TRẠNG THÁI</th><th>THAO TÁC</th></tr></thead><tbody>${ms.map((m,i)=>`<tr><td>${esc(m.name)}<small>${esc(m.email)}</small></td><td>${esc(roleNames[m.role])}<small>${esc(scopeNames[m.scope_level])} · ${esc(m.team||'')}</small></td><td>${m.disabled?'Đã khóa':m.passwordReady?m.mustChange?'Cần đổi MK tạm':'Đang hoạt động':'Chưa đặt mật khẩu'}</td><td><button onclick="editMember(${i})">Sửa quyền</button>${m.email!==user.email?` <button onclick="resetMember(${i})">Cấp lại mật khẩu</button>`:''}</td></tr>`).join('')}</tbody></table></div>`;$('#auditlist').innerHTML='<h2>Nhật ký thay đổi</h2><div class="tablewrap"><table><tbody>'+logs.map(l=>`<tr><td>${esc(new Date(l.at).toLocaleString('vi-VN'))}</td><td>${esc(l.actor)}</td><td>${esc(l.operation)}</td></tr>`).join('')+'</tbody></table></div>'}catch(e){toast(e.message)}}
function editMember(i){let m=accountList[i],f=$('#memberform');for(let n of ['email','name','role','team'])f.elements[n].value=m[n]||'';f.elements.scope_level.value=['iid','department','personal'].includes(m.scope_level)?m.scope_level:'personal';f.elements.disabled.checked=m.disabled;f.elements.email.focus();}
async function resetMember(i){let m=accountList[i];if(!confirm('Cấp lại mật khẩu cho '+m.email+' và thu hồi các phiên đăng nhập cũ?'))return;try{let x=await req('/auth/reset-password','POST',{email:m.email});await loadAccountList();showTemporary(x.email,x.temporaryPassword)}catch(e){toast(e.message)}}
function renderScopedCascade(){let ks=state.kpis;$('#app').innerHTML=head('Mục tiêu trong phạm vi','Chỉ hiển thị mục tiêu liên quan đến cấp và tài khoản được giao.',true)+`<div class="panel"><h2>Liên kết mục tiêu</h2>${ks.map(k=>{let p=[...ks,...(state.references||[])].find(p=>p.id===k.parent);return `<div class="treeitem"><span class="badge">${esc(k.level)}</span> ${esc(k.name)}<p class="mini">${esc(k.owner)} · ${esc(k.team)}${p?' · Đóng góp vào '+esc(p.name):''}</p></div>`}).join('')||'<p>Chưa có KPI trong phạm vi.</p>'}</div>`;}
$('#logout').onclick=async()=>{try{await req('/auth/logout','POST',{});setupEmail=null;renderLogin()}catch(e){toast(e.message)}};
periodOptions();(async()=>{try{let x=await req('/auth/me');setupEmail=x.setupEmail;user=x.user;if(user)await enterWorkspace();else renderLogin()}catch(e){logoutUI();$('#app').innerHTML='<div class="panel"><h1>Kết nối tài khoản</h1><p>'+esc(e.message)+'</p><button onclick="location.reload()">Thử lại</button></div>'}})();
